2565     fn validate_slot_roster(
2566         release: &ProductReleaseId,
2567         approved: &[ApprovedRegistryPackage],
2568         slots: &[ReleaseArtifactSlot],
2569     ) -> Result<(), SuccessorError> {
2570         if slots.windows(2).any(|pair| pair[0] == pair[1]) {
2571             return Err(SuccessorError::DuplicateSlot);
2572         }
2573         for slot in slots {
2574             slot.validate(release)?;
2575         }
2576         let registry_slots = slots
2577             .iter()
2578             .filter_map(|slot| match slot {
2579                 ReleaseArtifactSlot::RegistryPackage {
2580                     package,
2581                     version,
2582                     registry,
2583                     format,
2584                     ..
2585                 } if version == &release.version => Some(ApprovedRegistryPackage {
2586                     package: package.clone(),
2587                     registry: registry.clone(),
2588                     format: format.clone(),
2589                 }),
2590                 _ => None,
2591             })
2592             .collect::<BTreeSet<_>>();
2593         if registry_slots.len()
2594             != slots
2595                 .iter()
2596                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
2597                 .count()
2598             || registry_slots.iter().ne(approved.iter())
2599         {
2600             return Err(SuccessorError::RegistrySlotOutsideApprovedRoster);
2601         }
2602         let targets: BTreeSet<_> = slots
2603             .iter()
2604             .filter_map(|slot| match slot {
2605                 ReleaseArtifactSlot::ProductAsset { target, .. } => Some(*target),
2606                 _ => None,
2607             })
2608             .collect();
2609         if slots
2610             .iter()
2611             .filter(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
2612             .count()
2613             != ProductTarget::ALL.len()
2614             || targets.len() != ProductTarget::ALL.len()
2615             || !ProductTarget::ALL.iter().all(|target| targets.contains(target))
2616             || slots
2617                 .iter()
2618                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
2619                 .count()
2620                 != 1
2621             || slots
2622                 .iter()
2623                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
2624                 .count()
2625                 != 1
2626         {
2627             return Err(SuccessorError::InvalidProductRoster);
2628         }
2629         let mut names = BTreeSet::new();
2630         if slots.iter().any(|slot| !names.insert(slot.file_name())) {
2631             return Err(SuccessorError::DuplicateFileName);
2632         }
2633         Ok(())
2634     }
