2782     fn digest_intent(
2783         release: &ProductReleaseId,
2784         source: &CommitSha,
2785         approved: &[ApprovedRegistryPackage],
2786         operations: &[ReleaseOperation],
2787         slots: &[ReleaseArtifactSlot],
2788     ) -> IntentDigest {
2789         let mut transcript = CanonicalTranscript::intent_v1();
2790         transcript.push_str("successor.schema", "1");
2791         transcript.push_str("product", release.product.as_str());
2792         transcript.push_str("product.version", release.version.render());
2793         transcript.push_str("source", source.as_str());
2794         for registry in approved {
2795             transcript.push_bytes(
2796                 "approved-registry",
2797                 serde_json::to_vec(registry).expect("closed roster serializes"),
2798             );
2799         }
2800         for operation in operations {
2801             transcript.push_bytes(
2802                 "operation",
2803                 serde_json::to_vec(&operation.id).expect("closed operation serializes"),
2804             );
2805             for prerequisite in &operation.prerequisites {
2806                 transcript.push_bytes(
2807                     "prerequisite",
2808                     serde_json::to_vec(prerequisite).expect("closed operation serializes"),
2809                 );
2810             }
2811         }
2812         for slot in slots {
2813             transcript.push_bytes("slot", serde_json::to_vec(slot).expect("closed slot serializes"));
2814         }
2815         IntentDigest::from_transcript(&transcript)
2816     }
