2636     fn validate_operations(
2637         release: &ProductReleaseId,
2638         approved: &[ApprovedRegistryPackage],
2639         operations: &[ReleaseOperation],
2640         slots: &[ReleaseArtifactSlot],
2641     ) -> Result<(), SuccessorError> {
2642         let ids: BTreeSet<_> = operations.iter().map(|operation| operation.id.clone()).collect();
2643         if ids.len() != operations.len() {
2644             return Err(SuccessorError::DuplicateOperation);
2645         }
2646         for operation in operations {
2647             operation.id.validate(release)?;
2648             if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1])
2649                 || operation.prerequisites.iter().any(|id| !ids.contains(id))
2650             {
2651                 return Err(SuccessorError::InvalidPrerequisite);
2652             }
2653         }
2654         let expected_uploads: BTreeSet<_> = slots.iter().filter(|slot| slot.release().is_some()).cloned().collect();
2655         let uploads: BTreeSet<_> = operations
2656             .iter()
2657             .filter_map(|operation| match &operation.id {
2658                 ReleaseOperationId::ArtifactUpload { slot, .. } => Some(slot.clone()),
2659                 _ => None,
2660             })
2661             .collect();
2662         if uploads != expected_uploads {
2663             return Err(SuccessorError::InvalidProductRoster);
2664         }
2665         let registry_operations: BTreeSet<_> = operations
2666             .iter()
2667             .filter_map(|operation| match &operation.id {
2668                 ReleaseOperationId::RegistryArtifactPublish { slot, .. } => Some(slot.clone()),
2669                 _ => None,
2670             })
2671             .collect();
2672         let registry_slots: BTreeSet<_> = slots
2673             .iter()
2674             .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
2675             .cloned()
2676             .collect();
2677         if registry_operations != registry_slots || registry_slots.len() != approved.len() {
2678             return Err(SuccessorError::InvalidPackageOperation);
2679         }
2680         let tags = operations
2681             .iter()
2682             .filter(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
2683             .collect::<Vec<_>>();
2684         let prepares = operations
2685             .iter()
2686             .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
2687             .collect::<Vec<_>>();
2688         let publishes = operations
2689             .iter()
2690             .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
2691             .collect::<Vec<_>>();
2692         if tags.len() != 1 || prepares.len() != 1 || publishes.len() != 1 {
2693             return Err(SuccessorError::InvalidProductOperation);
2694         }
2695         let mut registry_ids = operations
2696             .iter()
2697             .filter_map(|operation| {
2698                 matches!(operation.id, ReleaseOperationId::RegistryArtifactPublish { .. })
2699                     .then_some(operation.id.clone())
2700             })
2701             .collect::<Vec<_>>();
2702         registry_ids.sort();
2703         if tags[0].prerequisites != registry_ids
2704             || prepares[0].prerequisites != [tags[0].id.clone()]
2705             || operations.iter().any(|operation| {
2706                 matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. })
2707                     && operation.prerequisites != [prepares[0].id.clone()]
2708             })
2709         {
2710             return Err(SuccessorError::InvalidPrerequisite);
2711         }
2712         let prepare_repository = match &prepares[0].id {
2713             ReleaseOperationId::ForgePrepare { repository, .. } => repository,
2714             _ => unreachable!("filtered ForgePrepare"),
2715         };
2716         let publish_repository = match &publishes[0].id {
2717             ReleaseOperationId::ForgePublish { repository, .. } => repository,
2718             _ => unreachable!("filtered ForgePublish"),
2719         };
2720         if prepare_repository != publish_repository
2721             || slots
2722                 .iter()
2723                 .filter(|slot| slot.release().is_some())
2724                 .any(|slot| slot.policy().repository != *prepare_repository)
2725         {
2726             return Err(SuccessorError::MismatchedForgeRepository);
2727         }
2728         let mut upload_ids = operations
2729             .iter()
2730             .filter_map(|operation| {
2731                 matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }).then_some(operation.id.clone())
2732             })
2733             .collect::<Vec<_>>();
2734         upload_ids.sort();
2735         if publishes[0].prerequisites != upload_ids {
2736             return Err(SuccessorError::InvalidPrerequisite);
2737         }
2738         let edges: BTreeMap<_, _> = operations
2739             .iter()
2740             .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
2741             .collect();
2742         let canonical = stable_order(&edges)?;
2743         if operations.iter().map(|operation| &operation.id).ne(canonical.iter()) {
2744             return Err(SuccessorError::NonCanonicalOperationOrder);
2745         }
2746         Ok(())
2747     }
