2749     fn stable_order(
2750         prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
2751     ) -> Result<Vec<ReleaseOperationId>, SuccessorError> {
2752         let mut remaining: BTreeMap<_, _> = prerequisites
2753             .iter()
2754             .map(|(id, prerequisites)| (id.clone(), prerequisites.len()))
2755             .collect();
2756         let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
2757         for (id, prerequisites) in prerequisites {
2758             for prerequisite in prerequisites {
2759                 dependents.entry(prerequisite.clone()).or_default().push(id.clone());
2760             }
2761         }
2762         let mut ready: BTreeSet<_> = remaining
2763             .iter()
2764             .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
2765             .collect();
2766         let mut ordered = Vec::with_capacity(prerequisites.len());
2767         while let Some(id) = ready.pop_first() {
2768             ordered.push(id.clone());
2769             for dependent in dependents.get(&id).into_iter().flatten() {
2770                 let count = remaining.get_mut(dependent).expect("known successor node");
2771                 *count -= 1;
2772                 if *count == 0 {
2773                     ready.insert(dependent.clone());
2774                 }
2775             }
2776         }
2777         (ordered.len() == prerequisites.len())
2778             .then_some(ordered)
2779             .ok_or(SuccessorError::CyclicPrerequisites)
2780     }
