2785         approved: &[ApprovedRegistryPackage],
2786         operations: &[ReleaseOperation],
2787         slots: &[ReleaseArtifactSlot],
2788     ) -> IntentDigest {
2789         let mut transcript = CanonicalTranscript::intent_v1();
2790         transcript.push_str("successor.schema", "1");
